//! Numerical parity of the Rust NeMo front end with NeMo's own
//! preprocessor, exported to ONNX by onnx-asr (`nemo128.onnx`,
//! `nemo80.onnx`).
//!
//! Reference files are generated by
//! `tools/model-export/make_feature_refs.py` (developer-only Python) into a
//! folder named by `SWIFTVOICE_FEATURE_REF`; the test is skipped when it is
//! not set.

use std::path::PathBuf;

use swiftvoice::asr::features::NemoMel;

fn read_f32(path: &std::path::Path) -> Vec<f32> {
    let bytes = std::fs::read(path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    bytes.as_chunks::<4>().0.iter().map(|b| f32::from_le_bytes(*b)).collect()
}

#[test]
fn rust_features_match_nemo_reference() {
    let Some(dir) = std::env::var_os("SWIFTVOICE_FEATURE_REF").map(PathBuf::from) else {
        eprintln!("skipping: set SWIFTVOICE_FEATURE_REF to a folder made by make_feature_refs.py");
        return;
    };
    let meta: serde_json::Value = serde_json::from_str(&std::fs::read_to_string(dir.join("meta.json")).unwrap()).unwrap();
    for signal in ["speech", "synthetic"] {
        let audio = read_f32(&dir.join(format!("{signal}.f32")));
        for mels in [128usize, 80] {
            let key = format!("{signal}_nemo{mels}");
            let m = &meta[&key];
            let frames = m["shape"][1].as_u64().unwrap() as usize;
            let valid = m["len"].as_u64().unwrap() as usize;
            let reference = read_f32(&dir.join(format!("{key}.f32")));
            let mut mel = NemoMel::new(mels);
            let (ours, t, v) = mel.compute(&audio);
            assert_eq!((t, v), (frames, valid), "{key}: frame counts");
            let mut max_diff = 0f32;
            let mut sum_diff = 0f64;
            for b in 0..mels {
                for f in 0..valid {
                    let d = (ours[b * t + f] - reference[b * frames + f]).abs();
                    max_diff = max_diff.max(d);
                    sum_diff += d as f64;
                }
            }
            let mean_diff = sum_diff / (mels * valid) as f64;
            eprintln!("{key}: {mels}x{valid} features, max |diff| {max_diff:.2e}, mean |diff| {mean_diff:.2e}");
            // Features are normalised to unit variance; float32 FFT and log
            // rounding leave differences far below 1e-2.
            assert!(max_diff < 2e-2, "{key}: max diff {max_diff}");
            assert!(mean_diff < 1e-3, "{key}: mean diff {mean_diff}");
        }
    }
}
